// Trafik ışığı: kırmızı → kırmızı+sarı → yeşil → sarı → kırmızı...
const int KIRMIZI_PIN = 10;
const int SARI_PIN = 9;
const int YESIL_PIN = 8;

void isiklar(bool kirmizi, bool sari, bool yesil) {
  digitalWrite(KIRMIZI_PIN, kirmizi);
  digitalWrite(SARI_PIN, sari);
  digitalWrite(YESIL_PIN, yesil);
}

void setup() {
  Serial.begin(9600);
  pinMode(KIRMIZI_PIN, OUTPUT);
  pinMode(SARI_PIN, OUTPUT);
  pinMode(YESIL_PIN, OUTPUT);
}

void loop() {
  Serial.println("Kirmizi");
  isiklar(true, false, false);
  delay(3000);
  Serial.println("Kirmizi + sari");
  isiklar(true, true, false);
  delay(1000);
  Serial.println("Yesil");
  isiklar(false, false, true);
  delay(3000);
  Serial.println("Sari");
  isiklar(false, true, false);
  delay(1000);
}
